sections.code:
.carte {
  padding: 1.5rem; /* Espace intérieur. */
  border: 1px solid #d4dfd5;
  margin-bottom: 1rem; /* Espace extérieur. */
}

*, *::before, *::after {
  box-sizing: border-box;
}

header, main, footer {
  width: 100%; max-width: 70rem;
  margin-inline: auto; padding: 1.5rem;
}
section { margin-block: 2rem; }

.carte {
  border-radius: 0.75rem;
  box-shadow: 0 0.25rem 0.75rem rgb(0 0 0 / 8%);
}
.intro {
  padding: 2rem;
  background: linear-gradient(135deg, #e4efdc, #f6f8f5);
}
img { max-width: 100%; height: auto; }

